// Pseudo-code: forward pass
const vector = encoder.encode(inputText, language);
const logit = classifier.predict(vector, language);
const sentiment = softmax(logit);
if (sentiment.negative > threshold) {
  publishEscalation(inputText, sentiment);
}
```

